INSERT INTO `wp_options` VALUES (1817,'_transient_modula_all_packages','a:1:{s:15:\"upsell_packages\";a:5:{s:37:\"modula-grid-gallery-business-lifetime\";a:6:{s:4:\"name\";s:41:\"Modula Grid Gallery - Business (lifetime)\";s:13:\"upgrade_price\";s:6:\"345.00\";s:4:\"slug\";s:37:\"modula-grid-gallery-business-lifetime\";s:7:\"excerpt\";s:26:\"Build the perfect gallery.\";s:2:\"id\";i:538961;s:10:\"extensions\";a:24:{s:6:\"modula\";a:3:{s:4:\"name\";s:10:\"Modula PRO\";s:11:\"description\";s:129:\"Gives access to Modula Filters, Ordering and holds the main licensing functionality. You can\'t get automatic updates without it. \";s:4:\"slug\";s:17:\"modula/Modula.php\";}s:12:\"modula-video\";a:3:{s:4:\"name\";s:5:\"Video\";s:11:\"description\";s:137:\"Adding a video gallery with both self-hosted videos and videos from sources like YouTube and Vimeo to your website has never been easier.\";s:4:\"slug\";s:29:\"modula-video/modula-video.php\";}s:14:\"modula-speedup\";a:3:{s:4:\"name\";s:7:\"SpeedUp\";s:11:\"description\";s:199:\"Allow Modula to automatically optimize your images to load as fast as possible by reducing their file sizes, resizing them through ShortPixel and serve them from StackPath\'s content delivery network.\";s:4:\"slug\";s:33:\"modula-speedup/modula-speedup.php\";}s:26:\"modula-advanced-shortcodes\";a:3:{s:4:\"name\";s:18:\"Advanced Shortcode\";s:11:\"description\";s:118:\"Allows you to dynamically link to specific galleries without creating pages for them by using URLs with query strings.\";s:4:\"slug\";s:57:\"modula-advanced-shortcodes/modula-advanced-shortcodes.php\";}s:17:\"modula-protection\";a:3:{s:4:\"name\";s:22:\"Right-Click Protection\";s:11:\"description\";s:199:\"The Modula Protection extension allows you to easily prevent your visitors from downloading your images with right-click protection. Use this extension to retain full ownership of your creative work.\";s:4:\"slug\";s:39:\"modula-protection/modula-protection.php\";}s:15:\"modula-deeplink\";a:3:{s:4:\"name\";s:12:\"SEO Deeplink\";s:11:\"description\";s:101:\"Full SEO control over your galleries. Create a unique and indexable URL for each Modula Gallery item.\";s:4:\"slug\";s:35:\"modula-deeplink/modula-deeplink.php\";}s:16:\"modula-watermark\";a:3:{s:4:\"name\";s:9:\"Watermark\";s:11:\"description\";s:101:\"Easily protect your photos by adding custom watermarks to your WordPress image galleries with Modula.\";s:4:\"slug\";s:37:\"modula-watermark/modula-watermark.php\";}s:23:\"modula-password-protect\";a:3:{s:4:\"name\";s:26:\"Password Protect Galleries\";s:11:\"description\";s:91:\"Password protect your galleries. This is a perfect solution for exclusive client galleries!\";s:4:\"slug\";s:51:\"modula-password-protect/modula-password-protect.php\";}s:16:\"modula-slideshow\";a:3:{s:4:\"name\";s:18:\"Lightbox Slideshow\";s:11:\"description\";s:98:\"Automatically turn your lightbox images into an auto-play slideshow. Play & pause between images. \";s:4:\"slug\";s:37:\"modula-slideshow/modula-slideshow.php\";}s:13:\"modula-slider\";a:3:{s:4:\"name\";s:25:\"Convert Gallery to Slider\";s:11:\"description\";s:116:\"Ever wanted to be able to create a gallery slider? One big image with thumbnail navigation below? We got it covered.\";s:4:\"slug\";s:31:\"modula-slider/modula-slider.php\";}s:13:\"modula-albums\";a:3:{s:4:\"name\";s:14:\"Gallery Albums\";s:11:\"description\";s:179:\"Give your galleries a place to call home with the Albums addon. Create albums, add galleries, manage cover photos, show gallery titles and even image counts in this superb add-on!\";s:4:\"slug\";s:31:\"modula-albums/modula-albums.php\";}s:11:\"modula-exif\";a:3:{s:4:\"name\";s:4:\"EXIF\";s:11:\"description\";s:88:\"The EXIF Addon for Modula allows you to edit & display EXIF metadata in your lightboxes.\";s:4:\"slug\";s:27:\"modula-exif/modula-exif.php\";}s:15:\"modula-download\";a:3:{s:4:\"name\";s:8:\"Download\";s:11:\"description\";s:103:\"Give your users the ability to downloa