ass\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/First_pass.gif\",\"data-width\":4,\"data-height\":5},{\"id\":\"124\",\"alt\":\"Effects\",\"title\":\"Effects\",\"description\":\"Small straight ahead animation on feet and cloth animation detail\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":598,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/effects.gif\",\"data-width\":4,\"data-height\":3},{\"id\":\"28\",\"alt\":\"Second pass\",\"title\":\"Second pass\",\"description\":\"Second pass\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/05/Line.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"129\",\"alt\":\"Tie down\",\"title\":\"Tie down\",\"description\":\"Tie down\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Tied.gif\",\"data-width\":2,\"data-height\":2}],\"galleryId\":526,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":125,\"date\":\"2024-06-18T17:24:14\",\"date_gmt\":\"2024-06-18T17:24:14\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=125\"},\"modified\":\"2024-06-26T19:59:21\",\"modified_gmt\":\"2024-06-26T19:59:21\",\"slug\":\"animated-dunk-process\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=animated-dunk-process\",\"title\":{\"rendered\":\"Animated dunk process\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"lightbox\":\"fancybox\",\"show_navigation\":true,\"shuffle\":\"0\",\"titleColor\":\