INSERT INTO `wp_posts` VALUES (115,1,'2024-06-17 18:13:42','2024-06-17 18:13:42','<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:embed {\"url\":\"https://vimeo.com/960509618?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-1-1 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-1-1 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/960509618?share=copy\n</div></figure>\n<!-- /wp:embed --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-base-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:paragraph {\"style\":{\"typography\":{\"lineHeight\":\"1.2\"}},\"fontSize\":\"x-large\"} -->\n<p class=\"has-x-large-font-size\" style=\"line-height:1.2\">Animated dunk</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\"}},\"typography\":{\"lineHeight\":\"2\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:0px;padding-bottom:0px;line-height:2\">Personal project (Feb 2024) <br><strong>Tools: </strong>Procreate dreams</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Floating through the skies, <em>papa jump </em>defying physics. Following through Numencaniq’s <a href=\"https://www.domestika.org/en/courses/235-animacion-2d-con-photoshop-dibujo-camara-y-accion\">2D camera course</a>, which is focused on framing and camera movements, I went through an experimentation path with Procreate Dreams. By planning the animation beforehand I was able to think on ways to exaggarate the elongated and agile nature of a dunk though cameras and timing. Being able to have a mental map of what a flat movement could be allowed me to go quick and not overthink each of the positions, focusing on the impressions.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"40%\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"260px\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:40%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"60%\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:60%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"blockGap\":\"0\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"0px\"},\"border\":{\"radius\":\"0px\"}},\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group has-base-background-color has-background\" style=\"border-radius:0px;min-height:0px;margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:image {\"id\":86,\"width\":\"600px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"right\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|duotone-1\"},\"border\":{\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image alignright size-full is-resized has-custom-border\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/poses.png\" alt=\"\" class=\"wp-image-86\" style=\"border-radius:0px;width:600px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"top\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}},\"border\":{\"width\":\"0px\",\"style\":\"none\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"orientation\":\"horizontal\",\"verticalAlignment\":\"top\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\" style=\"border-style:none;border-width:0px;margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--30);padding-left:0\"><!-- wp:image {\"id\":84,\"width\":\"300px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"right\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|duotone-1\"}}} -->\n<figure class=\"wp-block-image alignright size-full is-resized\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/character.png\" alt=\"\" class=\"wp-image-84\" style=\"width:300px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":28,\"width\":\"300px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"left\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|duotone-1\"}}} -->\n<figure class=\"wp-block-image alignleft size-full is-resized\"><img src=\"http://localhost:10003/wp-content/uploads/2024/05/Line.gif\" alt=\"\" class=\"wp-image-28\" style=\"width:300px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":104,\"width\":\"300px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"left\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|duotone-1\"}}} -->\n<figure class=\"wp-block-image alignleft size-full is-resized\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/head.gif\" alt=\"\" class=\"wp-image-104\" style=\"width:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->','Animated dunk','','inherit','closed','closed','','23-revision-v1','','','2024-06-17 18:13:42','2024-06-17 18:13:42','',23,'http://localhost:10003/?p=115',0,'revision','',0);
