INSERT INTO `wp_posts` VALUES (135,1,'2024-06-18 18:20:21','2024-06-18 18:20:21','<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"66.66%\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"700px\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:embed {\"url\":\"https://vimeo.com/960509618?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-1-1 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-1-1 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/960509618?share=copy\n</div></figure>\n<!-- /wp:embed --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--20);flex-basis:33.33%\"><!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Animated dunk</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\"}},\"typography\":{\"lineHeight\":\"2\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:0px;padding-bottom:0px;line-height:2\">Personal project (Feb 2024) <br><strong>Tools: </strong>Procreate dreams</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Floating through the skies,&nbsp;<em>papa jump&nbsp;</em>defying physics. Following through Numencaniq’s&nbsp;<a href=\"https://www.domestika.org/en/courses/235-animacion-2d-con-photoshop-dibujo-camara-y-accion\">2D camera course</a>, which is focused on framing and camera movements, I went through an experimentation path with Procreate Dreams. By planning the animation beforehand I was able to think on ways to exaggarate the elongated and agile nature of a dunk though cameras and timing. Being able to have a mental map of what a flat movement could be allowed me to go quick and not overthink each of the positions, focusing on the impressions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"150px\"} -->\n<div style=\"height:150px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>In chronological order, click to enhance.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:modula/gallery {\"id\":125,\"images\":[{\"id\":\"124\",\"alt\":\"Smoke effect on feet animation\",\"title\":\"Effects\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":598,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/effects.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"123\",\"alt\":\"Three different timings variations\",\"title\":\"Timings\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Timings.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"120\",\"alt\":\"First pass\",\"title\":\"First pass\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/firstpass.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"118\",\"alt\":\"Planning\",\"title\":\"Planning\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Planning-1024x1024.png\",\"data-width\":2,\"data-height\":2},{\"id\":\"119\",\"alt\":\"Tiedown\",\"title\":\"Tiedown\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Tiedown.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"116\",\"alt\":\"Character\",\"title\":\"Character\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Character-1024x1024.png\",\"data-width\":2,\"data-height\":2},{\"id\":\"117\",\"alt\":\"Sketches\",\"title\":\"Sketches\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Sketches-1024x1024.png\",\"data-width\":2,\"data-height\":2},{\"id\":\"28\",\"alt\":\"Second pass\",\"title\":\"Second pass\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/05/Line.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"86\",\"alt\":\"Character poses\",\"title\":\"character poses\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/poses.png\",\"data-width\":2,\"data-height\":2},{\"id\":\"104\",\"alt\":\"Rotating character head\",\"title\":\"character head\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/head.gif\",\"data-width\":2,\"data-height\":2}],\"galleryId\":217,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":125,\"date\":\"2024-06-18T17:24:14\",\"date_gmt\":\"2024-06-18T17:24:14\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=125\"},\"modified\":\"2024-06-18T17:24:14\",\"modified_gmt\":\"2024-06-18T17:24:14\",\"slug\":\"animated-dunk-process\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=animated-dunk-process\",\"title\":{\"rendered\":\"Animated dunk process\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"creative-gallery\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"medium\",\"grid_image_dimensions\":{\"width\":0,\"height\":0},\"img_size\":200,\"img_crop\":true,\"grid_image_crop\":\"0\",\"gutter\":10,\"tablet_gutter\":10,\"mobile_gutter\":10,\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"shuffle\":\"0\",\"lightbox\":\"fancybox\",\"show_navigation\":true,\"hide_title\":true,\"titleColor\":\"\",\"titleFontSize\":0,\"mobileTitleFontSize\":12,\"hide_description\":\"0\",\"captionColor\":\"#ffffff\",\"captionFontSize\":14,\"mobileCaptionFontSize\":10,\"enableSocial\":\"0\",\"enableTwitter\":\"0\",\"enableFacebook\":\"0\",\"enableWhatsapp\":\"0\",\"enableLinkedin\":\"0\",\"enablePinterest\":\"0\",\"enableEmail\":\"0\",\"emailSubject\":\"Check out this awesome 