INSERT INTO `wp_posts` VALUES (149,1,'2024-06-25 17:58:07','2024-06-25 17:58:07','<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"45%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"right\":\"100px\",\"left\":\"100px\"}}},\"className\":\"top-video\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-column top-video\" style=\"padding-top:0;padding-right:100px;padding-bottom:0;padding-left:100px;flex-basis:45%\"><!-- wp:embed {\"url\":\"https://vimeo.com/960509618?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-1-1 wp-has-aspect-ratio\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-1-1 wp-has-aspect-ratio\" style=\"margin-right:0;margin-left:0\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/960509618?share=copy\n</div></figure>\n<!-- /wp:embed --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"2rem\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:2rem;padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0;flex-basis:33.33%\"><!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Animated dunk</h1>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\"}},\"typography\":{\"lineHeight\":\"2\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:0px;padding-bottom:0px;line-height:2\">Personal project (Feb 2024) <br><strong>Tools: </strong>Procreate dreams</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Floating through the skies,&nbsp;<em>papa jump&nbsp;</em>defying physics. Following through Numencaniq’s&nbsp;<a href=\"https://www.domestika.org/en/courses/235-animacion-2d-con-photoshop-dibujo-camara-y-accion\">2D camera course</a>, which is focused on framing and camera movements, I went through an experimentation path with Procreate Dreams. By planning the animation beforehand I was able to think on ways to exaggarate the elongated and agile nature of a dunk though cameras and timing. Being able to have a mental map of what a flat movement could be allowed me to go quick and not overthink each of the positions, focusing on the impressions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"150px\"} -->\n<div style=\"height:150px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>In chronological order, click to enhance.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:modula/gallery {\"id\":125,\"images\":[{\"id\":\"117\",\"alt\":\"Sketches\",\"title\":\"Sketches\",\"description\":\"Initial sketches\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Sketches-1024x1024.png\",\"data-width\":2,\"data-height\":2},{\"id\":\"104\",\"alt\":\"Rotating character head\",\"title\":\"character head\",\"description\":\"character turnaround\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/head.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"146\",\"alt\":\"Character\",\"title\":\"characterdesign\",\"description\":\"Character\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/characterdesign-1024x1024.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"118\",\"alt\":\"Planning\",\"title\":\"Planning\",\"description\":\"Planning\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Planning-1024x1024.png\",\"data-width\":4,\"data-height\":3},{\"id\":\"86\",\"alt\":\"Character poses\",\"title\":\"character poses\",\"description\":\"Exploring character poses\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/poses.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"126\",\"alt\":\"Varying animation timings\",\"title\":\"Varying animation timings\",\"description\":\"Experimenting three different spacings and timing\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/AnimationTimings.gif\",\"data-width\":4,\"data-height\":4},{\"id\":\"127\",\"alt\":\"First pass\",\"title\":\"First pass\",\"description\":\"First pass\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/First_pass.gif\",\"data-width\":4,\"data-height\":5},{\"id\":\"124\",\"alt\":\"Effects\",\"title\":\"Effects\",\"description\":\"Small straight ahead animation on feet and cloth animation detail\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":598,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/effects.gif\",\"data-width\":4,\"data-height\":3},{\"id\":\"28\",\"alt\":\"Second pass\",\"title\":\"Second pass\",\"description\":\"Second pass\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/05/Line.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"129\",\"alt\":\"Tie down\",\"title\":\"Tie down\",\"description\":\"Tie down\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Tied.gif\",\"data-width\":2,\"data-height\":2}],\"galleryId\":644,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":125,\"date\":\"2024-06-18T17:24:14\",\"date_gmt\":\"2024-06-18T17:24:14\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=125\"},\"modified\":\"2024-06-18T18:41:29\",\"modified_gmt\":\"2024-06-18T18:41:29\",\"slug\":\"animated-dunk-process\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=animated-dunk-process\",\"title\":{\"rendered\":\"Animated dunk process\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"large\",\"grid_image_dimensions\":{\"width\":0,\"height\":0},\"img_size\":200,\"img_crop\":true,\"grid_image_crop\":\"0\",\"gutter\":10,\"tablet_gutter\":10,\"mobile_gutter\":10,\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"shuffle\":\"0\",\"lightbox\":\"fancybox\",\"show_navigation\":true,\"hide_tit