>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost:10003/projects/\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10)\">Back to projects</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->','Animated dunk','','inherit','closed','closed','','23-revision-v1','','','2024-06-25 19:27:29','2024-06-25 19:27:29','',23,'http://localhost:10003/?p=179',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (181,1,'2024-06-26 16:10:16','2024-06-26 16:10:16','<!-- wp:embed {\"url\":\"https://vimeo.com/968201658?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/968201658?share=copy\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--10)\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}},\"typography\":{\"lineHeight\":\"2\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);line-height:2\">Commercial project (February 2023)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}},\"typography\":{\"lineHeight\":\"2\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);line-height:2\"><br><strong>Tools: </strong>Adobe Illustrator, After Effects<br><strong>Animation, sound and illustrations:  </strong>Pablo Fraustro<br><strong>Quality check: </strong>Carlos Torres</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">While working at <a href=\"http://cixi.life\" data-type=\"link\" data-id=\"cixi.life\">CIXI</a>, a French startup revolutionizing pedaling technology, I contributed to digital products and design studies for over two years. This video marked a pivotal moment as we prepared to introduce our innovation to the world. The project was meticulously crafted, with every word and visual element carefully designed to convey our message effectively.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:separator {\"className\":\"is-style-default\"} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-default\"/>\n<!-- /wp:separator -->\n\n<!-- wp:block {\"ref\":177} /-->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:modula/gallery {\"id\":168,\"images\":[{\"id\":\"170\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/3-1024x576.png\",\"data-width\":7,\"data-height\":6},{\"id\":\"169\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/2-1024x576.png\",\"data-width\":5,\"data-height\":3},{\"id\":\"171\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",