INSERT INTO `wp_posts` VALUES (183,1,'2024-06-26 19:24:11','2024-06-26 19:24:11','<!-- wp:embed {\"url\":\"https://vimeo.com/716351661?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/716351661?share=copy\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:33.33%\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|10\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-left\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--40)\">Baxter social campagin</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--40);flex-basis:66.66%\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"typography\":{\"lineHeight\":\"2.1\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0;line-height:2.1\"><strong>Tools: </strong>Adobe Photoshop, After Effects<br><strong>Category:</strong> Commercial project<br><strong>Animation, and illustrations:  </strong>Misael Naranjo, Pablo Fraustro<br><strong>Sound: </strong>Pablo Fraustro</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">During the pandemic, we were approached by TakeOff Productions and Baxter to create animations that would respond to the prevailing uncertainty. Despite the difficult times, the playful animations we crafted conveyed a sense of satisfaction and comfort, perfectly complementing their products</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10)\">Process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<p class=\"has-text-align-center\" style=\"padding-right:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)\">Given a defined style and initial sketches, we centered the animation around the product, using a muted palette and sketchy style to highlight its importance. This project involved an intense collaborative process between teams in Mexico and Italy. By working in shifts, we adhered to a tight schedule, sourcing content from the internet or recording it ourselves. We then created reference videos, rotoscoped the footage (intertwining drawings), and added various elements to complete the animations.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:modula/gallery {\"id\":265,\"images\":[{\"id\":\"267\",\"alt\":\"\",\"title\":\"006\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":819,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/006-819x1024.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"278\",\"alt\":\"\",\"title\":\"001\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":819,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/001-2-819x1024.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"277\",\"alt\":\"\",\"title\":\"asd\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":819,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/asd-819x1024.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"275\",\"alt\":\"\",\"title\":\"bongos\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":819,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/bongos-819x1024.png\",\"data-width\":8,\"data-height\":4},{\"id\":\"276\",\"alt\":\"\",\"title\":\"001\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":819,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/001-1-819x1024.png\",\"data-width\":4,\"data-height\":4}],\"galleryId\":181,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":265,\"date\":\"2024-06-26T19:43:53\",\"date_gmt\":\"2024-06-26T19:43:53\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=265\"},\"modified\":\"2024-06-27T16:16:00\",\"modified_gmt\":\"2024-06-27T16:16:00\",\"slug\":\"baxter\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=baxter\",\"title\":{\"rendered\":\"Baxter\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"full\",\"grid_image_dimensions\":{\"width\":0,\"height\":0},\"img_size\":200,\"img_crop\":true,\"grid_image_crop\":\"0\",\"gutter\":10,\"tablet_gutter\":10,\"mobile_gutter\":10,\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"shuffle\":\"0\",\"lightbox\":\"fancybox\",\"show_navigation\":true,\"hide_title\":true,\"titleColor\":\"\",\"titleFontSize\":0,\"mobileTitleFontSize\":12,\"hide_description\":\"0\",\"captionColor\":\"#ffffff\",\"captionFontSize\":14,\"mobileCaptionFontSize\":10,\"enableSocial\":\"0\",\"enableTwitter\":\"0\",\"enableFacebook\":\"0\",\"enableWhatsapp\":\"0\",\"enableLinkedin\":\"0\",\"enablePinterest\":\"0\",\"enableEmail\":\"0\",\"emailSubject\":\"Check out this awesome image !!\",\"emailMessage\":\"Here is the link to the image : %%image_link%% and this is the link to the gallery : %%gallery_link%%\",\"socialIconColor\":\"#ffffff\",\"socialIconSize\":16,\"socialIconPadding\":10,\"loadedScale\":100,\"inView\":\"0\",\"effect\":\"pufrobo\",\"cursor\":\"zoom-in\",\"borderSize\":0,\"borderRadius\":0,\"borderColor\":\"#ffffff\",\"shadowSize\":0,\"shadowColor\":\"#ffffff\",\"lazy_load\":true,\"enable_responsive\":true,\"tablet_columns\":1,\"mobile_columns\":1,\"style\":\"\",\"last_visited_tab\":\"modula-responsive\",\"helpergrid\":0},\"_links\":{\"self\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/modula-gallery/265\"}],\"collection\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/modula-gallery\"}],\"about\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/types/modula-gallery\"}],\"wp:attachment\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/media?parent=265\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https://api.w.org/{rel}\",\"templated\":true}]}},\"currentSelectize\":[{\"value\":265,\"label\":\"Baxter\"}]} /-->\n\n<!-- wp:block {\"ref\":253} /-->','Baxter','','publish','closed','closed','','baxter','','','2024-12-23 13:00:49','2024-12-23 11:00:49','',620,'http://localhost:10003/?page_id=183',0,'page','',0);
INSERT INTO `wp_posts` VALUES (185,1,'2024-06-26 16:21:46','2024-06-26 16:21:46','<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"45%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"right\":\"100px\",\"left\":\"100px\"}}},\"className\":\"top-video\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center top-video\" style=\"padding-top:0;padding-right:100px;padding-bottom:0;padding-left:100px;flex-basis:45%\"><!-- wp:embed {\"url\":\"https://vimeo.com/960509618?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-1-1 wp-has-aspect-ratio\",\"style\":{\"spacing\":{\"margin\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-1-1 wp-has-aspect-ratio\" style=\"margin-right:0;margin-left:0\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/960509618?share=copy\n</div></figure>\n<!-- /wp:embed --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"2rem\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:2rem;padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0;flex-basis:33.33%\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Animated dunk</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\"}},\"typography\":{\"lineHeight\":\"2\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:0px;padding-bottom:0px;line-height:2\"><br><strong>Tools: </strong>Procreate dreams<br><strong>Category: </strong>Personal project</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Floating through the skies, <em>papa jump </em>defying physics. Following through Numencaniq’s <a href=\"https://www.domestika.org/en/courses/235-animacion-2d-con-photoshop-dibujo-camara-y-accion\">2D camera course</a>, which is focused on framing and camera movements, I went through an experimentation path with Procreate Dreams. By planning the animation beforehand I was able to think on ways to exaggarate the elongated and agile nature of a dunk though cameras and timing. Being able to have a mental map of what a flat movement could be allowed me to go quick and not overthink each of the positions, focusing on the impressions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}},\"className\":\"is-style-default\"} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-default\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10)\">Process</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:modula/gallery {\"id\":125,\"images\":[{\"id\":\"117\",\"alt\":\"Sketches\",\"title\":\"Sketches\",\"description\":\"Initial sketches\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Sketches-1024x1024.png\",\"data-width\":2,\"data-height\":2},{\"id\":\"104\",\"alt\":\"Rotating character head\",\"title\":\"character head\",\"description\":\"character turnaround\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/head.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"146\",\"alt\":\"Character\",\"title\":\"characterdesign\",\"description\":\"Character\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/characterdesign-1024x1024.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"118\",\"alt\":\"Planning\",\"title\":\"Planning\",\"description\":\"Planning\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Planning-1024x1024.png\",\"data-width\":4,\"data-height\":3},{\"id\":\"86\",\"alt\":\"Character poses\",\"title\":\"character poses\",\"description\":\"Exploring character poses\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/poses.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"126\",\"alt\":\"Varying animation timings\",\"title\":\"Varying animation timings\",\"description\":\"Experimenting three different spacings and timing\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/AnimationTimings.gif\",\"data-width\":4,\"data-height\":4},{\"id\":\"127\",\"alt\":\"First pass\",\"title\":\"First pass\",\"description\":\"First pass\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/First_pass.gif\",\"data-width\":4,\"data-height\":5},{\"id\":\"124\",\"alt\":\"Effects\",\"title\":\"Effects\",\"description\":\"Small straight ahead animation on feet and cloth animation detail\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":598,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/effects.gif\",\"data-width\":4,\"data-height\":3},{\"id\":\"28\",\"alt\":\"Second pass\",\"title\":\"Second pass\",\"description\":\"Second pass\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/05/Line.gif\",\"data-width\":2,\"data-height\":2},{\"id\":\"129\",\"alt\":\"Tie down\",\"title\":\"Tie down\",\"description\":\"Tie down\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":600,\"height\":600,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Tied.gif\",\"data-width\":2,\"data-height\":2}],\"galleryId\":933,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":125,\"date\":\"2024-06-18T17:24:14\",\"date_gmt\":\"2024-06-18T17:24:14\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=125\"},\"modified\":\"2024-06-18T18:41:29\",\"modified_gmt\":\"2024-06-18T18:41:29\",\"slug\":\"animated-dunk-process\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=animated-dunk-process\",\"title\":{\"rendered\":\"Animated dunk process\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"large\",\"grid_image_dimensions\":{\"width\":0,\"