INSERT INTO `wp_posts` VALUES (242,1,'2024-06-26 16:56:04','2024-06-26 16:56:04','<!-- wp:embed {\"url\":\"https://vimeo.com/968201658?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/968201658?share=copy\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40)\"><!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-left\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">CIXI - Active vehicles</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--40);flex-basis:66.66%\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"typography\":{\"lineHeight\":\"2.1\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0;line-height:2.1\"><strong>Tools: </strong>Adobe Illustrator, After Effects<br><strong>Animation, sound and illustrations:  </strong>Pablo Fraustro<br><strong>Quality check: </strong>Carlos Torres<br><strong>Category:</strong> Commercial project</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">While working at <a href=\"http://cixi.life\" data-type=\"link\" data-id=\"cixi.life\">CIXI</a>, a French startup revolutionizing pedaling technology, I contributed to digital products and design studies for over two years. This video marked a pivotal moment as we prepared to introduce our innovation to the world. The project was meticulously crafted, with every word and visual element carefully designed to convey our message effectively.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--10)\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--40)\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10)\">Process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<p class=\"has-text-align-center\" style=\"padding-right:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)\">We began by defining all the visuals to align with the voiceover, focusing on themes of vision and active mobility. This led to the creation of diverse and imaginative vehicles and characters pedaling. Technically, most elements were created in Adobe Illustrator and then imported into After Effects.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"30px\"} -->\n<div style=\"height:30px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:modula/gallery {\"id\":168,\"images\":[{\"id\":\"170\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/3-1024x576.png\",\"data-width\":7,\"data-height\":6},{\"id\":\"169\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/2-1024x576.png\",\"data-width\":5,\"data-height\":3},{\"id\":\"171\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/4-1024x576.png\",\"data-width\":5,\"data-height\":3},{\"id\":\"172\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/5-1024x576.png\",\"data-width\":12,\"data-height\":6},{\"id\":\"173\",\"alt\":\"People styleframe\",\"title\":\"People styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/people_2-1024x576.png\",\"data-width\":14,\"data-height\":6}],\"galleryId\":55,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":168,\"date\":\"2024-06-25T19:06:20\",\"date_gmt\":\"2024-06-25T19:06:20\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=168\"},\"modified\":\"2024-06-25T19:10:32\",\"modified_gmt\":\"2024-06-25T19:10:32\",\"slug\":\"cixi\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=cixi\",\"title\":{\"rendered\":\"CIXI\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"medium\",\"grid_image_dimensions\":{\"width\":0,\"height\":0},\"img_size\":200,\"img_crop\":true,\"grid_image_crop\":\"0\",\"gutter\":10,\"tablet_gutter\":10,\"mobile_gutter\":10,\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"shuffle\":\"0\",\"lightbox\":\"fancybox\",\"show_navigation\":true,\"hide_title\":true,\"titleColor\":\"\",\"titleFontSize\":0,\"mobileTitleFontSize\":12,\"hide_description\":\"0\",\"captionColor\":\"#ffffff\",\"captionFontSize\":14,\"mobileCaptionFontSize\":10,\"enableSocial\":\"0\",\"enableTwitter\":\"0\",\"enableFacebook\":\"0\",\"enableWhatsapp\":\"0\",\"enableLinkedin\":\"0\",\"enablePinterest\":\"0\",\"enableEmail\":\"0\",\"emailSubject\":\"Check out this awesome image !!\",\"emailMessage\":\"Here is the link to the image : %%image_link%% and this is the link to the gallery : %%gallery_link%%\",\"socialIconColor\":\"#ffffff\",\"socialIconSize\":16,\"socialIconPadding\":10,\"loadedScale\":100,\"inView\":\"0\",\"effect\":\"pufrobo\",\"cursor\":\"zoom-in\",\"borderSize\":0,\"borderRadius\":0,\"borderColor\":\"#ffffff\",\"shadowSize\":0,\"shadowColor\":\"#ffffff\",\"lazy_load\":true,\"enable_responsive\":\"0\",\"tablet_columns\":2,\"mobile_columns\":1,\"style\":\"\",\"last_visited_tab\":\"modula-general\",\"helpergrid\":0},\"_links\":{\"self\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/modula-gallery/168\"}],\"collection\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/modula-gallery\"}],\"about\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/types/modula-gallery\"}],\"wp:attachment\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/media?parent=168\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https://api.w.org/{rel}\",\"templated\":true}]}},\"currentSelectize\":[{\"value\":168,\"label\":\"CIXI\"}]} /-->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:block {\"ref\":159} /-->','CIXI','','inherit','closed','closed','','160-revision-v1','','','2024-06-26 16:56:04','2024-06-26 16:56:04','',160,'http://localhost:10003/?p=242',0,'revision','',0);
