INSERT INTO `wp_posts` VALUES (323,1,'2024-06-27 14:53:27','2024-06-27 14:53:27','<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20);flex-basis:33.33%\"><!-- wp:image {\"id\":322,\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/Foto-el-27-06-2024-a-las-16.31-5.jpg\" alt=\"\" class=\"wp-image-322\" style=\"object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:paragraph -->\n<p>A crazy old man </p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->','About','','inherit','closed','closed','','142-revision-v1','','','2024-06-27 14:53:27','2024-06-27 14:53:27','',142,'http://localhost:10003/?p=323',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (324,1,'2024-06-27 15:14:58','2024-06-27 15:14:58','<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20);flex-basis:33.33%\"><!-- wp:image {\"id\":322,\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/Foto-el-27-06-2024-a-las-16.31-5.jpg\" alt=\"\" class=\"wp-image-322\" style=\"object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">About</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Pablo is a 2D animator and illustrator with a background in interaction design from Politecnico di Milano and engineering. He has a strong sense of creative exploration and is skilled at organizing and streamlining complex processes. Pablo enjoys working at the intersection of human anatomy, graphical design and animation, creating dynamic characters that move in engaging and lifelike ways.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->','About','','inherit','closed','closed','','142-revision-v1','','','2024-06-27 15:14:58','2024-06-27 15:14:58','',142,'http://localhost:10003/?p=324',0,'revision','',0);
