INSERT INTO `wp_posts` VALUES (390,1,'2024-06-27 16:52:39','2024-06-27 16:52:39','<!-- wp:spacer {\"height\":\"81px\"} -->\n<div style=\"height:81px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|40\",\"right\":\"0px\"}},\"typography\":{\"lineHeight\":\"1.2\"}},\"className\":\"animator\",\"fontSize\":\"x-large\"} -->\n<p class=\"animator has-x-large-font-size\" style=\"margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:var(--wp--preset--spacing--40);line-height:1.2\">2D animator and illustrator. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}},\"typography\":{\"lineHeight\":\"1.2\"}},\"fontSize\":\"x-large\"} -->\n<p class=\"has-x-large-font-size\" style=\"padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40);line-height:1.2\">Exploring motion and play ✏︎  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:modula/gallery {\"id\":314,\"images\":[{\"id\":\"170\",\"alt\":\"CIXI Active Vehicles project\",\"title\":\"CIXI Active Vehicles\",\"description\":\"Animating the future of mobility\",\"halign\":\"center\",\"valign\":\"bottom\",\"link\":\"http://localhost:10003/cixi/\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/3-1024x576.png\",\"data-width\":4,\"data-height\":4},{\"id\":\"267\",\"alt\":\"Baxter project\",\"title\":\"Baxter\",\"description\":\"Baxter playful animations\",\"halign\":\"center\",\"valign\":\"bottom\",\"link\":\"http://localhost:10003/baxter/\",\"target\":0,\"width\":819,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://