INSERT INTO `wp_posts` VALUES (500,1,'2024-07-01 17:53:58','2024-07-01 15:53:58','<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top:var(--wp--preset--spacing--40)\"><!-- wp:column {\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--40);flex-basis:33.33%\"><!-- wp:image {\"id\":322,\"aspectRatio\":\"3/4\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":\"0px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/Foto-el-27-06-2024-a-las-16.31-5.jpg\" alt=\"\" class=\"wp-image-322\" style=\"border-style:none;border-width:0px;border-radius:0px;aspect-ratio:3/4;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"66.66%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-right:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--30);flex-basis:66.66%\"><!-- wp:heading {\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<h1 class=\"wp-block-heading\" style=\"padding-top:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20)\">About</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"left\":\"0\"}}}} -->\n<p style=\"padding-left:0\">Pablo is a 2D animator and illustrator with a background in interaction design from Politecnico di Milano and engineering. He has a strong sense of creative exploration and is skilled at organizing and streamlining complex processes. Pablo enjoys working at the intersection of human anatomy, graphical design and animation, creating dynamic characters that move in engaging and lifelike ways.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:social-links {\"iconColor\":\"contrast-3\",\"iconColorValue\":\"#A4A4A4\",\"openInNewTab\":true,\"size\":\"has-normal-icon-size\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"0\",\"right\":\"0\"},\"blockGap\":{\"top\":\"0\",\"left\":\"var:preset|spacing|10\"}}},\"className\":\"is-style-logos-only\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\"}} -->\n<ul class=\"wp-block-social-links has-normal-icon-size has-icon-color is-style-logos-only\" style=\"margin-top:var(--wp--preset--spacing--30);margin-right:0;margin-bottom:var(--wp--preset--spacing--30);margin-left:0\"><!-- wp:social-link {\"url\":\"https://www.instagram.com/pablo.fraustro/?hl=it\",\"service\":\"instagram\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.linkedin.com/in/pablo-fraustro-24058569/\",\"service\":\"linkedin\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://vimeo.com/user95124936\",\"service\":\"vimeo\"} /-->\n\n<!-- wp:social-link {\"url\":\"ciclos.00-gubia@icloud.com\",\"service\":\"mail\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->','About','','inherit','closed','closed','','142-revision-v1','','','2024-07-01 17:53:58','2024-07-01 15:53:58','',142,'http://localhost:10003/?p=500',0,'revision','',0);
