INSERT INTO `wp_posts` VALUES (642,1,'2024-07-29 21:21:54','2024-07-29 19:21:54','<!-- wp:spacer {\"height\":\"81px\"} -->\n<div style=\"height:81px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\",\"right\":\"0px\"},\"padding\":{\"top\":\"0px\",\"bottom\":\"0px\",\"left\":\"var:preset|spacing|40\",\"right\":\"0px\"}},\"typography\":{\"lineHeight\":\"0.5\"}},\"className\":\"animator\",\"fontSize\":\"large\"} -->\n<p class=\"animator has-large-font-size\" style=\"margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:var(--wp--preset--spacing--40);line-height:0.5\">Hello! I\'m Pablo, </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|30\"}},\"typography\":{\"lineHeight\":\"1.2\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\" style=\"padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--40);line-height:1.2\">2D animator and illustrator.  ✏︎</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:modula/gallery {\"id\":314,\"images\":[{\"id\":\"537\",\"alt\":\"extreme dunk\",\"title\":\"extreme dunk\",\"description\":\"An animated dunk\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"http://localhost:10003/animated-dunk/\",\"target\":0,\"width\":1016,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/Captura-de-pantalla-2024-07-25-a-las-11.37.27-1016x1024.png\",\"data-width\":6,\"data-height\":4},{\"id\":\"567\",\"alt\":\"Mini jazz\",\"title\":\"Mini jazz\",\"description\":\"Mini jazz explosion\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"http://localhost:10003/mini-jazz/\",\"target\":0,\"width\":1024,\"height\":1024,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/07/minijaz-1024x1024.png\",\"data-width\":6,\"data-height\":4},{\"id\":\"170\",\"alt\":\"CIXI Active Vehicles project\",\"title\":\"CIXI Active Vehicles\",\"description\":\"Animating the future of mobility\",\"halign\":\"center\",\"valign\":\"bottom\",\"link\":\"http://localhost:10003/cixi/\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/3-1024x576.png\",\"data-width\":6,\"data-height\":4},{\"id\":\"483\",\"alt\":\"Experiments\",\"title\":\"Experiments\",\"description\":\"Small animation loops\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"http://localhost:10003/animation-experiments/\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/07/unnamed-file-1024x576.png\",\"data-width\":6,\"data-height\":4},{\"id\":\"568\",\"alt\":\"Baxter\",\"title\":\"Baxter\",\"description\":\"Baxter playful animations\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"http://localhost:10003/baxter/\",\"target\":0,\"width\":1024,\"height\":675,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/07/Captura-de-pantalla-2024-07-25-a-las-13.17.23-1024x675.png\",\"data-width\":6,\"data-height\":4}],\"galleryId\":363,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":314,\"date\":\"2024-06-26T20:53:17\",\"date_gmt\":\"2024-06-26T20:53:17\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=314\"},\"modified\":\"2024-07-25T15:06:03\",\"modified_gmt\":\"2024-07-25T13:06:03\",\"slug\":\"projects\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=projects\",\"title\":{\"rendered\":\"Projects\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"large\",\"grid_image_dimensions\":{\"width\":0,\"height\":0},\"img_size\":200,\"img_crop\":true,\"grid_image_crop\":\"0\",\"gutter\":10,\"tablet_gutter\":10,\"mobile_gutter\":10,\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"shuffle\":\"0\",\"lightbox\":\"external-url\",\"show_navigation\":true,\"hide_title\":true,\"titleColor\":\"\",\"titleFontSize\":0,\"mobileTitleFontSize\":12,\"hide_description\":\"0\",\"captionColor\":\"#ffffff\",\"captionFontSize\":14,\"mobileCaptionFontSize\":10,\"enableSocial\":\"0\",\"enableTwitter\":\"0\",\"enableFacebook\":\"0\",\"enableWhatsapp\":\"0\",\"enableLinkedin\":true,\"enablePinterest\":\"1\",\"enableEmail\":\"0\",\"emailSubject\":\"Check out this awesome image !!\",\"emailMessage\":\"Here is the link to the image : %%image_link%% and this is the link to the gallery : %%gallery_link%%\",\"socialIconColor\":\"#ffffff\",\"socialIconSize\":16,\"socialIconPadding\":10,\"loadedScale\":100,\"inView\":\"0\",\"effect\":\"pufrobo\",\"cursor\":\"pointer\",\"borderSize\":0,\"borderRadius\":0,\"borderColor\":\"#ffffff\",\"shadowSize\":0,\"shadowColor\":\"#ffffff\",\"lazy_load\":true,\"enable_responsive\":true,\"tablet_columns\":1,\"mobile_columns\":1,\"style\":\".modula-items .figc p.description { font-family: var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dfont-family\\u002d\\u002dmanrope) !important; font-size: var(\\u002d\\u002dwp\\u002d\\u002dpreset\\u002d\\u002dfont-size\\u002d\\u002dlarge) !important; font-style: normal; font-weight: 400 !important; color:black !important; line-height: 1.5rem !important; letter-spacing: 0px !important; } .modula .modula-item.effect-pufrobo p{ text-align:center !important;bottom:50% !important;transform: translateY(50%) !important; } html body .modula .modula-item.effect-pufrobo p.description { margin-bottom: 5px; }\",\"last_visited_tab\":\"modula-customizations\",\"helpergrid\":0},\"_links\":{\"self\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/modula-gallery/314\"}],\"collection\":[{\"h