INSERT INTO `wp_posts` VALUES (684,1,'2024-07-29 21:39:42','2024-07-29 19:39:42','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0\">A startup in the French alps developing mobility solutions that work for an adoption of physical activity and overall wellness through electric pedaling vehicles and their technology.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As an interaction and motion designer, I’ve been involved in the following projects:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>Onboard screens and design research</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Communicating our startup – Website design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Understanding CIXI’s role – Communication</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','CIXI','','inherit','closed','closed','','618-revision-v1','','','2024-07-29 21:39:42','2024-07-29 19:39:42','',618,'http://localhost:10003/?p=684',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (685,1,'2024-07-29 21:48:55','2024-07-29 19:48:55','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0\">A startup in the French alps developing mobility solutions that work for an adoption of physical activity and overall wellness through electric pedaling vehicles and their technology.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As an interaction and motion designer, I’ve been involved in the following projects:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>Onboard screens and design research</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Communicating our startup – Website design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Understanding CIXI’s role – Communication</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Onboard screens and design research</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Goal:</strong> Define and test user interactions on the Vigoz, a vehicle controlled by pedaling and tilting that arrives up to 120 km/h.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The possible users, as we discovered, were people interested on getting healthy, but not necessarily fit or energetic.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>So, How to define an interactive system to support changing the \"Effort level\" and making physical activity while keeping a certain premium feeling and of course, focusing on the ride ?</p>\n<!-- /wp:paragraph -->','CIXI','','inherit','closed','closed','','618-revision-v1','','','2024-07-29 21:48:55','2024-07-29 19:48:55','',618,'http://localhost:10003/?p=685',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (686,1,'2024-07-29 21:50:58','2024-07-29 19:50:58','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0\">A startup in the French alps developing mobility solutions that work for an adoption of physical activity and overall wellness through electric pedaling vehicles and their technology.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As an interaction and motion designer, I’ve been involved in the following projects:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>Onboard screens and design research</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Communicating our startup – Website design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Understanding CIXI’s role – Communication</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Onboard screens and design research</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Goal:</strong> Define and test user interactions on the Vigoz, a vehicle controlled by pedaling and tilting that arrives up to 120 km/h.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The possible users, as we discovered, were people interested on getting healthy, but not necessarily fit or energetic.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>So, How to define an interactive system to support changing the \"Effort level\" and making physical activity while keeping a certain premium feeling and of course, focusing on the ride ?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','CIXI','','inherit','closed','closed','','618-revision-v1','','','2024-07-29 21:50:58','2024-07-29 19:50:58','',618,'http://localhost:10003/?p=686',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (687,1,'2024-07-29 21:51:18','2024-07-29 19:51:18','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0\">A startup in the French alps developing mobility solutions that work for an adoption of physical activity and overall wellness through electric pedaling vehicles and their technology.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>As an interaction and motion designer, I’ve been involved in the following projects:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>Onboard screens and design research</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Communicating our startup – Website design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Understanding CIXI’s role – Communication</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:0;padding-left:0\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Onboard screens and design research</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Goal:</strong> Define and test user interactions on the Vigoz, a vehicle controlled by pedaling and tilting that arrives up to 120 km/h.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The possible users, as we discovered, were people interested on getting healthy, but not necessarily fit or energetic. So, How to define an interactive system to support changing the \"Effort level\" and making physical activity while keeping a certain premium feeling and of course, focusing on the ride ?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->','CIXI','','inherit','closed','closed','','618-revision-v1','','','2024-07-29 21:51:18','2024-07-29 19:51:18','',618,'http://localhost:10003/?p=687',0,'revision','',0);
