INSERT INTO `wp_posts` VALUES (811,1,'2024-07-30 12:50:58','2024-07-30 10:50:58','<!-- wp:group {\"metadata\":{\"name\":\"Heading\"},\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"className\":\"heading\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"30%\"}} -->\n<div class=\"wp-block-group heading\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--30)\">Lexus shaped by air</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--40);padding-left:0\">As part of the Milan Design week, Diorama partenered with Lexus to create an immersion in a deep forest, with threads of wind, rusty leaves and rays of light. From the individual forms of the Lexus Elecrified Sport coupe, this hypnotic interactive world sees the Lexus design language through the prism of nature’s cues. Inspired by the Japanese concept of ‘shine-to’ (like nature), the pieces come together to show what can happen when engineering and nature combine.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Content\"},\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"}}},\"className\":\"content\",\"layout\":{\"type\":\"constrained\",\"wideSize\":\"60%\"}} -->\n<div class=\"wp-block-group content\" style=\"padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:gallery {\"columns\":2,\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-2 is-cropped\"><!-- wp:image {\"id\":809,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/1-ezgif.com-crop.gif\" alt=\"\" class=\"wp-image-809\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":807,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/3-ezgif.com-crop.gif\" alt=\"\" class=\"wp-image-807\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":810,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/2-ezgif.com-crop-1.gif\" alt=\"\" class=\"wp-image-810\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"width\":100,\"style\":{\"border\":{\"radius\":\"0px\"},\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-100 has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://discoverlexus.com/stories/shaped-by-air-at-milan-design-week-2023/\" style=\"border-radius:0px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--30)\" target=\"_blank\" rel=\"noreferrer noopener\">Complete article</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"width\":100,\"style\":{\"border\":{\"radius\":\"0px\"},\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-width wp-block-button__width-100 has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://discoverlexus.com/stories/shaped-by-air-at-milan-design-week-2023-metaverse-experience/\" style=\"border-radius:0px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--30)\" target=\"_blank\" rel=\"noreferrer noopener\">Immersive experience</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->','Lexus shaped by air','','inherit','closed','closed','','790-revision-v1','','','2024-07-30 12:50:58','2024-07-30 10:50:58','',790,'http://localhost:10003/?p=811',0,'revision','',0);
