INSERT INTO `wp_posts` VALUES (997,1,'2024-09-11 11:21:58','2024-09-11 09:21:58','<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\" style=\"padding-top:var(--wp--preset--spacing--40)\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"33.33%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20);flex-basis:33.33%\"><!-- wp:image {\"id\":322,\"aspectRatio\":\"3/4\",\"scale\":\"cover\",\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"align\":\"right\",\"style\":{\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":\"0px\"}},\"className\":\"img-about\"} -->\n<figure class=\"wp-block-image alignright size-medium has-custom-border img-about\"><img src=\"http://localhost:10003/wp-content/uploads/2024/06/Foto-el-27-06-2024-a-las-16.31-5-217x300.jpg\" alt=\"\" class=\"wp-image-322\" style=\"border-style:none;border-width:0px;border-radius:0px;aspect-ratio:3/4;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"40%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|60\",\"left\":\"0\"}}},\"className\":\"prg-about\"} -->\n<div class=\"wp-block-column is-vertically-aligned-top prg-about\" style=\"padding-right:var(--wp--preset--spacing--60);padding-left:0;flex-basis:40%\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"1.5rem\",\"top\":\"var:preset|spacing|40\"}}},\"className\":\"img-about\"} -->\n<p class=\"has-text-align-left img-about\" style=\"padding-top:var(--wp--preset--spacing--40);padding-left:1.5rem\">As an interaction and motion designer, I have a passion for creative exploration and am skilled at organizing complex processes. Working at the intersection of technology and art, I believe true creativity isn\'t limited to a single profile or discipline. Meaningful collaboration and a thoughtful approach are essential to crafting experiences that exceed expectations.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:social-links {\"iconColor\":\"contrast-3\",\"iconColorValue\":\"#A4A4A4\",\"openInNewTab\":true,\"size\":\"has-normal-icon-size\",\"align\":\"left\",\"style\":{\"spacing\":{\"margin\":{\"left\":\"var:preset|spacing|10\",\"right\":\"0\",\"top\":\"40px\",\"bottom\":\"40px\"},\"blockGap\":{\"top\":\"7vw\",\"left\":\"20px\"}}},\"className\":\"is-style-logos-only icons-about\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"nowrap\"}} -->\n<ul class=\"wp-block-social-links alignleft has-normal-icon-size has-icon-color is-style-logos-only icons-about\" style=\"margin-top:40px;margin-right:0;margin-bottom:40px;margin-left:var(--wp--preset--spacing--10)\"><!-- wp:social-link {\"url\":\"https://www.instagram.com/pablo.fraustro/?hl=it\",\"service\":\"instagram\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://www.linkedin.com/in/pablo-fraustro-24058569/\",\"service\":\"linkedin\"} /-->\n\n<!-- wp:social-link {\"url\":\"https://vimeo.com/user95124936\",\"service\":\"vimeo\"} /-->\n\n<!-- wp:social-link {\"url\":\"ciclos.00-gubia@icloud.com\",\"service\":\"mail\"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->','About','','inherit','closed','closed','','142-revision-v1','','','2024-09-11 11:21:58','2024-09-11 09:21:58','',142,'http://localhost:10003/?p=997',0,'revision','',0);
