INSERT INTO `wp_posts` VALUES (1063,1,'2024-09-27 15:26:01','2024-09-27 13:26:01','<!-- wp:group {\"metadata\":{\"name\":\"Heading\"},\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"className\":\"heading\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group heading\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40)\">A digital exhibition</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"400px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|30\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--40)\">An exhibition hall, a 3D environment to settle the grounds for an exploration of Diorama\'s projects.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Content\"},\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"}}},\"className\":\"content\",\"layout\":{\"type\":\"constrained\",\"wideSize\":\"800px\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group content\" style=\"padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:image {\"id\":792,\"width\":\"800px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/initial-ezgif.com-optimize.gif\" alt=\"\" class=\"wp-image-792\" style=\"width:800px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--10)\"><!-- wp:spacer {\"height\":\"40px\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"border\":{\"radius\":\"0px\"},\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}},\"className\":\"is-style-outline\",\"fontSize\":\"medium\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-medium-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://diorama.eu\" style=\"border-radius:0px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--30)\">Explore website</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30)\"><strong>The labyrinth</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<p style=\"padding-right:0;padding-bottom:var(--wp--preset--spacing--40);padding-left:0\">A concept to showcase Diorama’s work, for the moment capable of instructions on where and what size to position work, this will allow anyone without experience of code to curate the interior.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":774,\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/lab.gif\" alt=\"\" class=\"wp-image-774\" style=\"object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30)\"><strong>Aesthetic exploration</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:paragraph -->\n<p>Creating websites its not an easy and direct task. There is always a balance between the visual experience and usability. Meaning we have to avocate for the smoothness and the sense of the experience as well.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This is why exploration of our limitations (like size of 3d models and lighting) guides our creativity to different areas.&nbsp;</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This way, we can share this experiences to anyone, anytime, anywhere in the world.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":775,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/image-868x1024.png\" alt=\"\" class=\"wp-image-775\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:image {\"id\":797,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/model-ezgif.com-optimize.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/model-ezgif.com-optimize.gif\" alt=\"\" class=\"wp-image-797\"/></a><figcaption class=\"wp-element-caption\">Importing 3d models</figcaption></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":796,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/materials-ezgif.com-optimize.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/materials-ezgif.com-optimize.gif\" alt=\"\" class=\"wp-image-796\"/></a><figcaption class=\"wp-element-caption\"> Materials and lighting</figcaption></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":795,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/camera-ezgif.com-optimize-1.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/camera-ezgif.com-optimize-1.gif\" alt=\"\" class=\"wp-image-795\"/></a><figcaption class=\"wp-element-caption\">Camera movements and navigation</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:block {\"ref\":840} /--></div>\n<!-- /wp:group -->','Diorama','','inherit','closed','closed','','770-revision-v1','','','2024-09-27 15:26:01','2024-09-27 13:26:01','',770,'http://localhost:10003/?p=1063',0,'revision','',0);
