INSERT INTO `wp_posts` VALUES (1152,1,'2024-09-27 17:30:40','2024-09-27 15:30:40','<!-- wp:group {\"metadata\":{\"name\":\"Heading\"},\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"className\":\"heading\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group heading\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--20)\">CIXI Active Vehicles</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"600px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:0;padding-left:0\">I worked with a French Alps startup on mobility solutions, contributing to early design and planning for a connected app, website, onboard screens, design research, and communication content.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:video {\"id\":1118} -->\n<figure class=\"wp-block-video\"><video autoplay controls loop muted src=\"http://localhost:10003/wp-content/uploads/2024/09/video_app.mp4\"></video></figure>\n<!-- /wp:video -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|10\",\"top\":\"var:preset|spacing|50\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--10)\">A connected app</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\">As part of a service exploration, we ventured into prototyping and designing an ultra-connected application that aligned with CIXI\'s mission of promoting health and wellness. We explored various features, including vehicle sharing, networking, renting, and seamless vehicle control.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<script>\n        function checkPassword() {\n            var password = document.getElementById(\'password\').value;\n            var correctPassword = \'sun8\'; \n            if (password === correctPassword) {\n                document.getElementById(\'login-form\').style.display = \'none\';\n                document.getElementsByClassName(\'protected-content\')[0].style.display = \'block\';\n            } else {\n                document.getElementById(\'message\').textContent = \'Incorrect password. Try again.\';\n            }\n        }\n    </script>\n<style>\n        .login-container { text-align: center; }\n        .hidden { display: none; }\n    </style>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"login-container\">\n        <div id=\"login-form\">\n \n         <p >Input password to unlock full page:</p>\n            <input style=\"padding-top:10px;padding-bottom:10px\"type=\"password\" id=\"password\" placeholder=\"Password\">\n            <button class=\"wp-block-button__link wp-element-button\" onclick=\"checkPassword()\">Submit</button>\n            <p id=\"message\" style=\"color: red;\"></p>\n        </div>\n    </div>\n<!-- /wp:html -->\n\n<!-- wp:separator {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--40)\"/>\n<!-- /wp:separator -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Content\"},\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"}}},\"className\":\"protected-content hidden\",\"layout\":{\"type\":\"constrained\",\"wideSize\":\"800px\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group protected-content hidden\" style=\"padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|10\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--10)\"><strong>Design research</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}},\"color\":{\"background\":\"#f1f1f1\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-background has-medium-font-size\" style=\"background-color:#f1f1f1;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Goal:&nbsp;Define and test user interactions on the Vigoz, a vehicle controlled by pedaling and tilting that arrives up to 120 km/h. This included: onboard screens, an app, website and overall service experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"0\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:0;padding-left:0\">The possible users, as we discovered, were people interested on getting healthy, but not necessarily fit or energetic. So, How to define an interactive system to support changing the \"Effort level\" and making physical activity while keeping a certain premium feeling and of course, focusing on the ride ?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"top\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:image {\"id\":644,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/prototypes.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/prototypes.png\" alt=\"\" class=\"wp-image-644\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\"}}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-medium-font-size\" style=\"padding-right:var(--wp--preset--spacing--20)\">To understand if this interactions could work, we tested “lego type” prototypes  to switch between different interaction interfaces and screens.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We conducted a second study, inviting potential customers to test a virtual reality pedaling environment to help us determine the best screens, handles, and features to include.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\" style=\"padding-top:var(--wp--preset--spacing--20)\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:image {\"id\":645,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/unnamed-1-1.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/unnamed-1-1.gif\" alt=\"\" class=\"wp-image-645\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Working with a team of three designers, we maximized our diverse skillsets during the sprint. Carlos (Head of Design at CIXI, with experience at IDEO and Lego) led the research, interviews, and designed the onboarding process. Daniel Sanchez (industrial designer) focused on handle designs and 3D-printed elements, while I handled digital prototypes and the \'magic wizard\' role.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\">The test consisted on going through a theoretical acquisition of a membership with the Vigoz through a web prototype, understanding client expectations, using a web app and pedaling on the cardboard prototype. We had really interesting results, realizing there was still a long path to support our philosophy and promote a new vehicle which is neither a bicycle nor a car.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:embed {\"url\":\"https://vimeo.com/723977908/e9b5b1c9c5\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"align\":\"wide\",\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed alignwide is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/723977908/e9b5b1c9c5\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:gallery {\"columns\":2,\"linkTo\":\"none\",\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|10\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"}}}} -->\n<figure class=\"wp-block-gallery alignfull has-nested-images columns-2 is-cropped\" style=\"margin-top:var(--wp--preset--spacing--50);margin-bottom:var(--wp--preset--spacing--50);padding-top:0;padding-bottom:0\"><!-- wp:image {\"id\":698,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0156-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0156-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-698\"/></a><figcaption class=\"wp-element-caption\">checking account</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":700,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/DSC00320-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/DSC00320-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-700\"/></a><figcaption class=\"wp-element-caption\">tracking tests</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":699,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0421-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0421-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-699\"/></a><figcaption class=\"wp-element-caption\">app</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":701,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0268-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0268-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-701\"/></a><figcaption class=\"wp-element-caption\">multiple interactions</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":702,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0444-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0444-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-702\"/></a><figcaption class=\"wp-element-caption\">pedalling</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":697,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0255-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0255-scaled-1-1024x575.jpg\" alt=\"\" class=\"wp-image-697\"/></a><figcaption class=\"wp-element-caption\">immersive prototyping</figcaption></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:0;padding-bottom:var(--wp--preset--spacing--30);padding-left:0\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|50\",\"right\":\"0\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:0;padding-bottom:var(--wp--preset--spacing--30)\"><strong>Website and content creation</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We went through a process of finding the best communication strategy to show our motivation as CIXI and a little bit of our products without showing too much.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>After some sketching and several graphic iterations, we focused on captivating interest through a combination of interactive animations by scrolling and \"easy-going\" animations by code (Lottie). </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\">Note: 3D render by Carlos Torres</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:gallery {\"linkTo\":\"none\",\"align\":\"wide\"} -->\n<figure class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":722,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/logo_animation_repeated.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/logo_animation_repeated.gif\" alt=\"\" class=\"wp-image-722\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":723,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/meditation_timing.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/meditation_timing-1024x1024.png\" alt=\"\" class=\"wp-image-723\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":724,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/essential-comfort_color_padding.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/essential-comfort_color_padding-1024x683.png\" alt=\"\" class=\"wp-image-724\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":709,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/bike.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/bike.png\" alt=\"\" class=\"wp-image-709\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":710,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/exam.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/exam.png\" alt=\"\" class=\"wp-image-710\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":711,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56xwnzu.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56xwnzu.gif\" alt=\"\" class=\"wp-image-711\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":712,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/fast_hyfit_1080_square.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/fast_hyfit_1080_square-1024x1024.gif\" alt=\"\" class=\"wp-image-712\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":713,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/hand.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/hand.png\" alt=\"\" class=\"wp-image-713\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":708,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56x6299.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56x6299.gif\" alt=\"\" class=\"wp-image-708\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":714,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/gif_1-1.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/gif_1-1.gif\" alt=\"\" class=\"wp-image-714\"/></a></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:paragraph -->\n<p>A mobile approach allowed us to expose our philosophy for people or companies that were curious, where we deep-fully engaged with the subjects that move us.It was also important for us to grow our subscribers, with a simple design and enough about us, we encouraged people to follow our path.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<p style=\"padding-bottom:var(--wp--preset--spacing--40)\">enjoyed being involved on the whole process of ideation, experimenting and co-creating how to communicate our vision. Flexibility, vision, getting into details and then at the big level where crucial points to arrive at this compromise of engaging, but simple introduction to what we are building.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":719,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"align\":\"full\"} -->\n<figure class=\"wp-block-image alignfull size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website-1-1024x750.jpg\" alt=\"\" class=\"wp-image-719\"/></a><figcaption class=\"wp-element-caption\">Mobile version</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":718,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"align\":\"full\"} -->\n<figure class=\"wp-block-image alignfull size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website_big.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website_big-1024x640.jpg\" alt=\"\" class=\"wp-image-718\"/></a><figcaption class=\"wp-element-caption\">Desktop version</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|10\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30)\">A small experiment of tackling an important subject : what we design and develop and its impact on the planet. It served a starting point to understand our communication tone, for sure there is much to do to have less impact on this planet.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:embed {\"url\":\"https://vimeo.com/991951744\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"align\":\"full\",\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed alignfull is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/991951744\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:block {\"ref\":840} /--></div>\n<!-- /wp:group -->','CIXI design','','inherit','closed','closed','','618-revision-v1','','','2024-09-27 17:30:40','2024-09-27 15:30:40','',618,'http://localhost:10003/?p=1152',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1153,1,'2024-09-27 17:31:09','2024-09-27 15:31:09','<!-- wp:group {\"metadata\":{\"name\":\"Heading\"},\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"className\":\"heading\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group heading\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--20)\">CIXI Active Vehicles</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"600px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:0;padding-left:0\">I worked with a French Alps startup on mobility solutions, contributing to early design and planning for a connected app, website, onboard screens, design research, and communication content.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:video {\"id\":1118} -->\n<figure class=\"wp-block-video\"><video autoplay controls loop muted src=\"http://localhost:10003/wp-content/uploads/2024/09/video_app.mp4\"></video></figure>\n<!-- /wp:video -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|10\",\"top\":\"var:preset|spacing|50\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--10)\">A connected app</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\">As part of a service exploration, we ventured into prototyping and designing an ultra-connected application that aligned with CIXI\'s mission of promoting health and wellness. We explored various features, including vehicle sharing, networking, renting, and seamless vehicle control.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<script>\n        function checkPassword() {\n            var password = document.getElementById(\'password\').value;\n            var correctPassword = \'sun8\'; \n            if (password === correctPassword) {\n                document.getElementById(\'login-form\').style.display = \'none\';\n                document.getElementsByClassName(\'protected-content\')[0].style.display = \'block\';\n            } else {\n                document.getElementById(\'message\').textContent = \'Incorrect password. Try again.\';\n            }\n        }\n    </script>\n<style>\n        .login-container { text-align: center; }\n        .hidden { display: none; }\n    </style>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<div class=\"login-container\">\n        <div id=\"login-form\">\n \n         <p >Input password to unlock full page:</p>\n            <input style=\"padding-top:10px;padding-bottom:10px\"type=\"password\" id=\"password\" placeholder=\"Password\">\n            <button class=\"wp-block-button__link wp-element-button\" onclick=\"checkPassword()\">Submit</button>\n            <p id=\"message\" style=\"color: red;\"></p>\n        </div>\n    </div>\n<!-- /wp:html -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Content\"},\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"}}},\"className\":\"protected-content hidden\",\"layout\":{\"type\":\"constrained\",\"wideSize\":\"800px\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group protected-content hidden\" style=\"padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|10\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--10)\"><strong>Design research</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"}},\"color\":{\"background\":\"#f1f1f1\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-background has-medium-font-size\" style=\"background-color:#f1f1f1;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--20)\">Goal:&nbsp;Define and test user interactions on the Vigoz, a vehicle controlled by pedaling and tilting that arrives up to 120 km/h. This included: onboard screens, an app, website and overall service experience.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"0\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:0;padding-left:0\">The possible users, as we discovered, were people interested on getting healthy, but not necessarily fit or energetic. So, How to define an interactive system to support changing the \"Effort level\" and making physical activity while keeping a certain premium feeling and of course, focusing on the ride ?</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"verticalAlignment\":\"top\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:image {\"id\":644,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/prototypes.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/prototypes.png\" alt=\"\" class=\"wp-image-644\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\"}}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-left has-medium-font-size\" style=\"padding-right:var(--wp--preset--spacing--20)\">To understand if this interactions could work, we tested “lego type” prototypes  to switch between different interaction interfaces and screens.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We conducted a second study, inviting potential customers to test a virtual reality pedaling environment to help us determine the best screens, handles, and features to include.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\" style=\"padding-top:var(--wp--preset--spacing--20)\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:image {\"id\":645,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/unnamed-1-1.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/unnamed-1-1.gif\" alt=\"\" class=\"wp-image-645\"/></a></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"flex-basis:50%\"><!-- wp:paragraph {\"fontSize\":\"medium\"} -->\n<p class=\"has-medium-font-size\">Working with a team of three designers, we maximized our diverse skillsets during the sprint. Carlos (Head of Design at CIXI, with experience at IDEO and Lego) led the research, interviews, and designed the onboarding process. Daniel Sanchez (industrial designer) focused on handle designs and 3D-printed elements, while I handled digital prototypes and the \'magic wizard\' role.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|30\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--30)\">The test consisted on going through a theoretical acquisition of a membership with the Vigoz through a web prototype, understanding client expectations, using a web app and pedaling on the cardboard prototype. We had really interesting results, realizing there was still a long path to support our philosophy and promote a new vehicle which is neither a bicycle nor a car.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:embed {\"url\":\"https://vimeo.com/723977908/e9b5b1c9c5\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"align\":\"wide\",\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed alignwide is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/723977908/e9b5b1c9c5\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:gallery {\"columns\":2,\"linkTo\":\"none\",\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|10\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"}}}} -->\n<figure class=\"wp-block-gallery alignfull has-nested-images columns-2 is-cropped\" style=\"margin-top:var(--wp--preset--spacing--50);margin-bottom:var(--wp--preset--spacing--50);padding-top:0;padding-bottom:0\"><!-- wp:image {\"id\":698,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0156-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0156-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-698\"/></a><figcaption class=\"wp-element-caption\">checking account</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":700,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/DSC00320-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/DSC00320-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-700\"/></a><figcaption class=\"wp-element-caption\">tracking tests</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":699,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0421-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0421-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-699\"/></a><figcaption class=\"wp-element-caption\">app</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":701,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0268-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0268-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-701\"/></a><figcaption class=\"wp-element-caption\">multiple interactions</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":702,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0444-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0444-scaled-1-1024x683.jpg\" alt=\"\" class=\"wp-image-702\"/></a><figcaption class=\"wp-element-caption\">pedalling</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":697,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0255-scaled-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/IMG_0255-scaled-1-1024x575.jpg\" alt=\"\" class=\"wp-image-697\"/></a><figcaption class=\"wp-element-caption\">immersive prototyping</figcaption></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"padding-right:0;padding-bottom:var(--wp--preset--spacing--30);padding-left:0\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|50\",\"right\":\"0\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:0;padding-bottom:var(--wp--preset--spacing--30)\"><strong>Website and content creation</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We went through a process of finding the best communication strategy to show our motivation as CIXI and a little bit of our products without showing too much.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>After some sketching and several graphic iterations, we focused on captivating interest through a combination of interactive animations by scrolling and \"easy-going\" animations by code (Lottie). </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\">Note: 3D render by Carlos Torres</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:gallery {\"linkTo\":\"none\",\"align\":\"wide\"} -->\n<figure class=\"wp-block-gallery alignwide has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":722,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/logo_animation_repeated.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/logo_animation_repeated.gif\" alt=\"\" class=\"wp-image-722\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":723,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/meditation_timing.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/meditation_timing-1024x1024.png\" alt=\"\" class=\"wp-image-723\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":724,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/essential-comfort_color_padding.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/essential-comfort_color_padding-1024x683.png\" alt=\"\" class=\"wp-image-724\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":709,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/bike.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/bike.png\" alt=\"\" class=\"wp-image-709\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":710,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/exam.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/exam.png\" alt=\"\" class=\"wp-image-710\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":711,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56xwnzu.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56xwnzu.gif\" alt=\"\" class=\"wp-image-711\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":712,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/fast_hyfit_1080_square.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/fast_hyfit_1080_square-1024x1024.gif\" alt=\"\" class=\"wp-image-712\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":713,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/hand.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/hand.png\" alt=\"\" class=\"wp-image-713\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":708,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56x6299.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/animation_500_l56x6299.gif\" alt=\"\" class=\"wp-image-708\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":714,\"sizeSlug\":\"large\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/gif_1-1.gif\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/gif_1-1.gif\" alt=\"\" class=\"wp-image-714\"/></a></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:paragraph -->\n<p>A mobile approach allowed us to expose our philosophy for people or companies that were curious, where we deep-fully engaged with the subjects that move us.It was also important for us to grow our subscribers, with a simple design and enough about us, we encouraged people to follow our path.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<p style=\"padding-bottom:var(--wp--preset--spacing--40)\">enjoyed being involved on the whole process of ideation, experimenting and co-creating how to communicate our vision. Flexibility, vision, getting into details and then at the big level where crucial points to arrive at this compromise of engaging, but simple introduction to what we are building.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":719,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"align\":\"full\"} -->\n<figure class=\"wp-block-image alignfull size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website-1.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website-1-1024x750.jpg\" alt=\"\" class=\"wp-image-719\"/></a><figcaption class=\"wp-element-caption\">Mobile version</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":718,\"sizeSlug\":\"large\",\"linkDestination\":\"media\",\"align\":\"full\"} -->\n<figure class=\"wp-block-image alignfull size-large\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website_big.jpg\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/Screens_website_big-1024x640.jpg\" alt=\"\" class=\"wp-image-718\"/></a><figcaption class=\"wp-element-caption\">Desktop version</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|10\"}}}} -->\n<p style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30)\">A small experiment of tackling an important subject : what we design and develop and its impact on the planet. It served a starting point to understand our communication tone, for sure there is much to do to have less impact on this planet.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:embed {\"url\":\"https://vimeo.com/991951744\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"align\":\"full\",\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed alignfull is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/991951744\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:block {\"ref\":840} /--></div>\n<!-- /wp:group -->','CIXI design','','inherit','closed','closed','','618-revision-v1','','','2024-09-27 17:31:09','2024-09-27 15:31:09','',618,'http://localhost:10003/?p=1153',0,'revision','',0);
