INSERT INTO `wp_posts` VALUES (1309,1,'2024-12-23 13:34:54','2024-12-23 11:34:54','<!-- wp:group {\"metadata\":{\"name\":\"Heading\"},\"className\":\"heading\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"600px\"}} -->\n<div class=\"wp-block-group heading\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--50)\">What feels real</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"400px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-contrast-color has-text-color has-link-color has-medium-font-size\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0\">Thesis work \"Impact of experimental animation on modern audiovisual experiences\" for Digital &amp; Interaction Design masters program on Politecnico di Milano.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Content\"},\"className\":\"content\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"}}},\"layout\":{\"type\":\"constrained\",\"wideSize\":\"800px\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group content\" style=\"padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:image {\"id\":757,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/brief.png\" alt=\"\" class=\"wp-image-757\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|20\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--20)\"><strong>Research background</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<p style=\"padding-right:0;padding-bottom:var(--wp--preset--spacing--30);padding-left:0\">The thesis proposes a new analysis point from a modern perspective, based on the two main areas of animation that formed the works we see today on motion design: orthodox and experimental (as defined by Paul Wells on his book “Defining animation”). It also questions the new possibility of merging factors from both into a new more dynamic perspective.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":758,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/Experimental.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/Experimental.png\" alt=\"\" class=\"wp-image-758\"/></a><figcaption class=\"wp-element-caption\">Experimental animation</figcaption></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":759,\"sizeSlug\":\"full\",\"linkDestination\":\"media\"} -->\n<figure class=\"wp-block-image size-full\"><a href=\"http://localhost:10003/wp-content/uploads/2024/07/Orthodox.png\" target=\"_blank\" rel=\"noreferrer noopener\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/Orthodox.png\" alt=\"\" class=\"wp-image-759\"/></a><figcaption class=\"wp-element-caption\">Orthodox animation</figcaption></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--30)\"><strong>Experimentation</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\",\"padding\":{\"right\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10);flex-basis:50%\"><!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">Two different types of animations regarding “Social distancing on times of coronavirus”&nbsp;were developed and tested with 20 people in order to measure emotional response.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":761,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:10003/wp-content/uploads/2024/07/double_diamon_process.png\" alt=\"\" class=\"wp-image-761\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:embed {\"url\":\"https://vimeo.com/991969556\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\" style=\"margin-top:var(--wp--preset--spacing--40)\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/991969556\n</div><figcaption class=\"wp-element-caption\">Test video based on Orthodox animation</figcaption></figure>\n<!-- /wp:embed -->\n\n<!-- wp:embed {\"url\":\"https://vimeo.com/991970680\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/991970680\n</div><figcaption class=\"wp-element-caption\">Test video based on Experimental animation</figcaption></figure>\n<!-- /wp:embed -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":3,\"style\":{\"spacing\":{\"padding\":{\"bottom\":\"var:preset|spacing|20\",\"top\":\"var:preset|spacing|40\"}}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--20)\"><strong>Insights</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>The value of experimenting with abstract capabilities was clearly evident, whilst having certain elements like humans or humanlike behavior was beneficial as well to promote the main communicational intentions. This opened up a discussion and further analysis to discover how on future audiovisual scenarios the value of experimenting and defining a motion language could clearly benefit the communicational intentions, specially speaking about interactive scenarios and future integration with new technology.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>See the full thesis&nbsp;<a href=\"https://www.politesi.polimi.it/handle/10589/167499\" target=\"_blank\" rel=\"noreferrer noopener\">here</a>.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:block {\"ref\":253} /-->','What feels real','','inherit','closed','closed','','756-revision-v1','','','2024-12-23 13:34:54','2024-12-23 11:34:54','',756,'http://localhost:10003/?p=1309',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1310,1,'2025-01-29 11:19:37','0000-00-00 00:00:00','','Auto Draft','','auto-draft','open','open','','','','','2025-01-29 11:19:37','0000-00-00 00:00:00','',0,'http://localhost:10003/?p=1310',0,'post','',0);
INSERT INTO `wp_posts` VALUES (1311,1,'2025-01-29 11:24:35','2025-01-29 09:24:35','<!-- wp:embed {\"url\":\"https://vimeo.com/968201658?share=copy\",\"type\":\"video\",\"providerNameSlug\":\"vimeo\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-vimeo wp-block-embed-vimeo wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://vimeo.com/968201658?share=copy\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50)\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:33.33%\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|10\"}}}} -->\n<h1 class=\"wp-block-heading has-text-align-left\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--40)\">CIXI - Active vehicles</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--40);flex-basis:66.66%\"><!-- wp:paragraph {\"align\":\"left\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"0\",\"right\":\"0\"}},\"typography\":{\"lineHeight\":\"2.1\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\",\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-left has-contrast-color has-text-color has-link-color has-small-font-size\" style=\"padding-top:var(--wp--preset--spacing--10);padding-right:0;padding-bottom:var(--wp--preset--spacing--10);padding-left:0;line-height:2.1\"><strong>Tools: </strong>Adobe Illustrator, After Effects<br><strong>Category:</strong> Commercial project<br><strong>Animation, sound and illustrations:  </strong>Pablo Fraustro<br><strong>Quality check: </strong>Carlos Torres</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\">While working at <a href=\"http://cixi.life\" data-type=\"link\" data-id=\"cixi.life\">CIXI</a>, a French startup revolutionizing pedaling technology, I contributed to digital products and design studies for over two years. This video marked a pivotal moment as we prepared to introduce our innovation to the world. The project was meticulously crafted, with every word and visual element carefully designed to convey our message effectively.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:0;padding-bottom:var(--wp--preset--spacing--30)\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"padding-top:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10)\">Process</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<p class=\"has-text-align-center\" style=\"padding-right:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)\">We began by defining all the visuals to align with the voiceover, focusing on themes of vision and active mobility. This led to the creation of diverse and imaginative vehicles and characters pedaling. Technically, most elements were created in Adobe Illustrator and then imported into After Effects.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:modula/gallery {\"id\":168,\"images\":[{\"id\":\"170\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/3-1024x576.png\",\"data-width\":7,\"data-height\":6},{\"id\":\"169\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/2-1024x576.png\",\"data-width\":5,\"data-height\":3},{\"id\":\"171\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/4-1024x576.png\",\"data-width\":5,\"data-height\":3},{\"id\":\"172\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/5-1024x576.png\",\"data-width\":12,\"data-height\":6},{\"id\":\"173\",\"alt\":\"People styleframe\",\"title\":\"People styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":1024,\"height\":576,\"togglelightbox\":0,\"src\":\"http://localhost:10003/wp-content/uploads/2024/06/people_2-1024x576.png\",\"data-width\":12,\"data-height\":6}],\"galleryId\":849,\"galleryType\":\"gallery\",\"currentGallery\":{\"id\":168,\"date\":\"2024-06-25T19:06:20\",\"date_gmt\":\"2024-06-25T19:06:20\",\"guid\":{\"rendered\":\"http://localhost:10003/?post_type=modula-gallery\\u0026#038;p=168\"},\"modified\":\"2024-06-27T16:16:09\",\"modified_gmt\":\"2024-06-27T16:16:09\",\"slug\":\"cixi\",\"status\":\"publish\",\"type\":\"modula-gallery\",\"link\":\"http://localhost:10003/?modula-gallery=cixi\",\"title\":{\"rendered\":\"CIXI\"},\"template\":\"\",\"modulaSettings\":{\"type\":\"custom-grid\",\"grid_type\":\"automatic\",\"grid_row_height\":250,\"grid_justify_last_row\":\"justify\",\"grid_image_size\":\"full\",\"grid_image_dimensions\":{\"width\":0,\"height\":0},\"img_size\":200,\"img_crop\":true,\"grid_image_crop\":\"0\",\"gutter\":10,\"tablet_gutter\":10,\"mobile_gutter\":10,\"width\":\"100%\",\"height\":[800,800,800],\"randomFactor\":50,\"shuffle\":\"0\",\"lightbox\":\"fancybox\",\"show_navigation\":true,\"hide_title\":true,\"titleColor\":\"\",\"titleFontSize\":0,\"mobileTitleFontSize\":12,\"hide_description\":\"0\",\"captionColor\":\"#ffffff\",\"captionFontSize\":14,\"mobileCaptionFontSize\":10,\"enableSocial\":\"0\",\"enableTwitter\":\"0\",\"enableFacebook\":\"0\",\"enableWhatsapp\":\"0\",\"enableLinkedin\":\"0\",\"enablePinterest\":\"0\",\"enableEmail\":\"0\",\"emailSubject\":\"Check out this awesome image !!\",\"emailMessage\":\"Here is the link to the image : %%image_link%% and this is the link to the gallery : %%gallery_link%%\",\"socialIconColor\":\"#ffffff\",\"socialIconSize\":16,\"socialIconPadding\":10,\"loadedScale\":100,\"inView\":\"0\",\"effect\":\"pufrobo\",\"cursor\":\"zoom-in\",\"borderSize\":0,\"borderRadius\":0,\"borderColor\":\"#ffffff\",\"shadowSize\":0,\"shadowColor\":\"#ffffff\",\"lazy_load\":true,\"enable_responsive\":true,\"tablet_columns\":1,\"mobile_columns\":1,\"style\":\"\",\"last_visited_tab\":\"modula-responsive\",\"helpergrid\":0},\"modulaImages\":[{\"id\":\"170\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":7,\"height\":6,\"togglelightbox\":0,\"url\":\"http://localhost:10003/wp-content/uploads/2024/06/3.png\"},{\"id\":\"169\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":5,\"height\":3,\"togglelightbox\":0,\"url\":\"http://localhost:10003/wp-content/uploads/2024/06/2.png\"},{\"id\":\"171\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":5,\"height\":3,\"togglelightbox\":0,\"url\":\"http://localhost:10003/wp-content/uploads/2024/06/4.png\"},{\"id\":\"172\",\"alt\":\"Vehicle styleframe\",\"title\":\"Vehicle styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":12,\"height\":6,\"togglelightbox\":0,\"url\":\"http://localhost:10003/wp-content/uploads/2024/06/5.png\"},{\"id\":\"173\",\"alt\":\"People styleframe\",\"title\":\"People styleframe\",\"description\":\"\",\"halign\":\"center\",\"valign\":\"middle\",\"link\":\"\",\"target\":0,\"width\":12,\"height\":6,\"togglelightbox\":0,\"url\":\"http://localhost:10003/wp-content/uploads/2024/06/people_2.png\"}],\"_links\":{\"self\":[{\"href\":\"http://localhost:10003/wp-json/wp/v2/modula-gallery/168\",\"targetHints\":{\"allow\":[\"GET\",\"POST\",\"PUT\",\"PATCH\",\"DELETE\"]}}],\"collection\":[{\"href\":\"http://localhost:1000